import{_ as e,o as d,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const _=JSON.parse('{"title":"워커 환경변수","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/ref-env"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/ref-env"}],["meta",{"property":"og:title","content":"워커 환경변수"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/ref-env.md","filePath":"docs/ref-env.md"}'),c={name:"docs/ref-env.md"};function a(n,t,s,i,p,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="워커-환경변수" tabindex="-1">워커 환경변수 <a class="header-anchor" href="#워커-환경변수" aria-label="Permalink to &quot;워커 환경변수&quot;">​</a></h1><p>워커 파일에서 <code>tick.sh</code>를 source하기 <strong>전에</strong> 값을 얹으면 기본값을 덮어씁니다. 꼭 있어야 하는 줄은 source 한 줄뿐이고, 아래는 전부 선택입니다. 실제 소스는 <a href="https://github.com/proofer-tech/dira/blob/master/tick.sh" target="_blank" rel="noreferrer"><code>tick.sh</code></a>에 있습니다.</p><h2 id="워커-설정값" tabindex="-1">워커 설정값 <a class="header-anchor" href="#워커-설정값" aria-label="Permalink to &quot;워커 설정값&quot;">​</a></h2><table tabindex="0"><thead><tr><th>변수</th><th>기본값</th><th>뜻</th></tr></thead><tbody><tr><td><code>TICKET_NAME</code></td><td>워커 파일명(<code>.sh</code> 제외)</td><td>로그 접두 + 티켓 <code>owner</code> 표기</td></tr><tr><td><code>TICKET_CWD</code></td><td>큐 루트의 부모</td><td>디스패치된 세션의 작업 디렉터리</td></tr><tr><td><code>TICKET_PERSONAS</code></td><td><code>&lt;루트&gt;/personas</code></td><td>페르소나 프로필 디렉터리</td></tr><tr><td><code>TICKET_PROTOCOLS</code></td><td><code>&lt;루트&gt;/protocols</code></td><td>협업 프로토콜 디렉터리. 안의 <code>AGENTS.md</code>가 전원 프롬프트에 실립니다</td></tr><tr><td><code>TICKET_CONTEXT</code></td><td>(없음)</td><td><code>(&quot;&lt;경로&gt;|&lt;설명&gt;&quot; ...)</code> 배열. 프롬프트 꼬리에 참조 자료로 붙습니다. 없는 경로는 건너뛰고 <code>WARN</code>만 남깁니다</td></tr><tr><td><code>TICKET_ENGINE</code></td><td><code>(claude -p --session-id &quot;{sid}&quot; --dangerously-skip-permissions --input-format stream-json --output-format stream-json --verbose)</code></td><td>실행 엔진 argv. <code>{prompt}</code>·<code>{sid}</code>가 실행 직전에 치환됩니다. 기본 엔진은 스트리밍 입력이라 최초 프롬프트도 stdin(FIFO)으로 들어갑니다. <a href="/docs/barge-in">도는 세션에 말 걸기</a>가 그 통로입니다</td></tr><tr><td><code>TICKET_PROMPT_FMT</code></td><td><code>%s 티켓을 확인해 주세요. (...)</code></td><td>printf 포맷. <code>%s</code> = 티켓 해시 하나뿐</td></tr><tr><td><code>TICKET_INPROGRESS</code></td><td><code>.wip</code></td><td>진행중 상태 파일명 접미사</td></tr><tr><td><code>TICKET_DONE</code></td><td><code>.done</code></td><td>완료 상태 파일명 접미사</td></tr><tr><td><code>TICKET_MAXRUN</code></td><td><code>5400</code>(초)</td><td>세션 1건 실행 상한. 초과 시 TERM → KILL 후 백로그 복귀</td></tr><tr><td><code>TICKET_FEED_TIMEOUT</code></td><td><code>120</code>(초)</td><td>최초 프롬프트가 FIFO를 다 통과할 때까지 기다리는 상한. 스트리밍 입력 엔진 전용이고, 엔진이 이 안에 stdin을 안 읽으면 <code>STALL</code>로 실패 처리합니다</td></tr></tbody></table><p>큐 루트는 설정값이 없습니다. 워커 파일이 놓인 자리가 그대로 루트를 정하기 때문입니다. 응답 JSON에서 실제 <code>session_id</code>를 읽어 frontmatter를 고쳐 쓰는 단계는 <code>claude</code> 엔진 전용이라, 다른 엔진을 쓰면 그냥 건너뜁니다.</p><h2 id="머신-로컬-상태" tabindex="-1">머신 로컬 상태 <a class="header-anchor" href="#머신-로컬-상태" aria-label="Permalink to &quot;머신 로컬 상태&quot;">​</a></h2><p>호출하는 시점의 환경변수로만 바뀝니다. 워커 파일에 적는 값이 아닙니다.</p><table tabindex="0"><thead><tr><th>변수</th><th>기본값</th><th>뜻</th></tr></thead><tbody><tr><td><code>TICKET_LOCAL</code></td><td><code>~/.config/dira</code></td><td>토큰(<code>oauth-token</code>)과 워커 락(<code>run/</code>)이 사는 자리. 큐 루트가 공유 드라이브에 있어도 여기는 이 머신만의 것입니다</td></tr></tbody></table><p>다음은 <a href="/docs/ref-cli">CLI</a>입니다.</p>',9)])])}const m=e(c,[["render",a]]);export{_ as __pageData,m as default};
